/*---
description: Dynamic RegExp without flags validates Unicode group names, including a Unicode 17 letter.
features: [ts-unicode-regexp, ts-unicode-sequences, ts-strings, ts-arrays, ts-iteration, ts-errors]
---*/
// Generated by tooling/unicode-cases/regexp.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, The design and Staying identical to node.
// Context: dynamic named-group parsing needs identifier data even without i, u or v.
const names: string[] = ["\u03c0", "\ua7ce", "\ud801\udc00", "\u03c0\u200d", "\u03c0\u200c", "\u03c0\u0301"];
for (const name of names) {
  const pattern = new RegExp("^(?<" + name + ">x)\\k<" + name + ">$");
  assert.sameValue(pattern.flags, "");
  const match = pattern.exec("\u0078\u0078");
  if (match === null || match.groups === undefined) throw new Test262Error("missing named group");
  assert.sameValue(match[0], "\u0078\u0078");
  assert.sameValue(match[0].length, 2);
  assert.sameValue(match.groups[name], "\u0078");
  assert.sameValue(match.groups[name].length, 1);
}
